package credentials

import (
	"errors"
	"fmt"
	"runtime"

	"github.com/zalando/go-keyring"
)

const (
	// keyringService is the service name every DevDesk secret is filed under.
	// It is what the entry is called in the host's store: `devdesk:<account>`
	// in the Windows Credential Manager, service `devdesk` in the macOS
	// Keychain, attribute `service=devdesk` in the Secret Service.
	keyringService = "devdesk"

	// keyringProbeAccount is read — never written — to find out whether a store
	// is reachable at all. A miss proves the backend answered; an error of any
	// other kind proves it did not.
	keyringProbeAccount = "devdesk-availability-probe"
)

// KeyringStorage keeps secrets in the host's own secret manager: the Windows
// Credential Manager, the macOS Keychain, or a Secret Service implementation on
// Linux and the BSDs. None of the three needs cgo and none of them writes the
// secret to a file DevDesk owns.
//
// This is the only storage that can honour "no secret is written to disk in
// plaintext" (§3.9). GitCredentialStorage delegates to whatever helper git is
// configured with, which may well be one that writes plaintext.
type KeyringStorage struct {
	context string
}

// NewKeyringStorage returns a store scoped to a DevDesk context. Two contexts
// pointing at the same host keep separate secrets, which is the property
// GitCredentialStorage has to work for (see its describe method).
func NewKeyringStorage(contextName string) *KeyringStorage {
	if contextName == "" {
		contextName = "default"
	}
	return &KeyringStorage{context: contextName}
}

// account builds the key a secret is filed under. The context comes first so
// that the entries of one context sort together when a user browses the store
// by hand.
func (k *KeyringStorage) account(url string) string {
	return k.context + "/" + url
}

// Save writes the secret to the host store, replacing any previous value.
func (k *KeyringStorage) Save(url, secret string) error {
	if err := keyring.Set(keyringService, k.account(url), secret); err != nil {
		return fmt.Errorf("%s: %w", KeyringName(), err)
	}
	return nil
}

// Load reads the secret back. A missing entry is an error, matching the rest of
// the Storage implementations.
func (k *KeyringStorage) Load(url string) (string, error) {
	secret, err := keyring.Get(keyringService, k.account(url))
	if errors.Is(err, keyring.ErrNotFound) {
		return "", fmt.Errorf("%w for %s (context: %s)", ErrNotFound, url, k.context)
	}
	if err != nil {
		return "", fmt.Errorf("%s: %w", KeyringName(), err)
	}
	return secret, nil
}

// Delete removes the secret. Deleting one that is not there succeeds: logout
// must not fail because the token was already gone.
func (k *KeyringStorage) Delete(url string) error {
	err := keyring.Delete(keyringService, k.account(url))
	if err == nil || errors.Is(err, keyring.ErrNotFound) {
		return nil
	}
	return fmt.Errorf("%s: %w", KeyringName(), err)
}

// KeyringAvailable reports whether the host store answers at all.
//
// The probe is a read of an account that is never written. A miss means the
// backend replied and simply holds nothing — the store works. Anything else is
// the backend being absent: no D-Bus session on a headless Linux box, no
// `security` binary, an OS with no provider compiled in.
//
// It is a read, so it can never leave anything behind if it is called on a
// machine where the store turns out to be unusable.
func KeyringAvailable() bool {
	_, err := keyring.Get(keyringService, keyringProbeAccount)
	return err == nil || errors.Is(err, keyring.ErrNotFound)
}

// KeyringName is what the host calls its secret store, for messages the user
// reads. Naming the actual store beats "the system keyring" when the point is
// to tell someone where their token went.
func KeyringName() string {
	switch runtime.GOOS {
	case "windows":
		return "Windows Credential Manager"
	case "darwin":
		return "macOS Keychain"
	default:
		return "Secret Service"
	}
}

package credentials

import (
	"bytes"
	"context"
	"os/exec"
	"strings"
	"time"
)

// Backend names where a secret actually ends up.
type Backend string

const (
	// BackendKeyring is the host's own secret manager. The only backend that
	// can promise the secret is not sitting in a plaintext file somewhere.
	BackendKeyring Backend = "keyring"

	// BackendGitCredential delegates to git's configured credential helper.
	// Honest only as far as that helper is: `store` writes plaintext, which is
	// why gitHelperUsable refuses it.
	BackendGitCredential Backend = "git-credential"

	// BackendMemory holds the secret for this session and nothing longer. It is
	// the fallback, and it is deliberately the worst one — see Selection.Detail.
	BackendMemory Backend = "memory"
)

// Preference values accepted from app.secret_backend in the configuration.
const (
	PreferenceAuto          = "auto"
	PreferenceKeyring       = "keyring"
	PreferenceGitCredential = "git-credential"
)

// gitConfigTimeout bounds the `git config` read that inspects the helper. Same
// reasoning as credentialTimeout: a blocked git call must not freeze the TUI.
const gitConfigTimeout = 2 * time.Second

// Selection is a storage together with the answer to "where does the secret go".
// The UI needs both: it has to tell the user which store a token was written
// to, and warn them when the answer is "nowhere that survives this session".
type Selection struct {
	Storage Storage
	Backend Backend

	// Detail is a sentence for the user, naming the store or explaining why
	// there is none. Always populated.
	Detail string
}

// Persists reports whether a secret saved here survives the process.
func (s Selection) Persists() bool {
	return s.Backend != BackendMemory
}

// Select resolves the storage for a context.
//
// The order is deliberate and there is exactly one destination — writing to
// several at once is what made the old "secure" option store the token in the
// credential manager *and* in a plaintext file (§3.9):
//
//  1. the host secret store, when one answers;
//  2. git's credential helper, when git is configured with one that does not
//     itself write plaintext;
//  3. memory, for this session only.
//
// preference comes from app.secret_backend and pins the head of that list.
// A pinned backend that turns out to be unreachable falls through to memory
// rather than silently to the other one: someone who asked for the keyring
// should not get a git helper without being told.
//
// The returned Selection must be kept for the lifetime of the context. Calling
// Select again yields a fresh MemoryStorage, and a token saved into the old one
// would be invisible to it.
func Select(contextName, preference string) Selection {
	switch preference {
	case PreferenceKeyring:
		if KeyringAvailable() {
			return keyringSelection(contextName)
		}
		return memorySelection(KeyringName() + " is configured but not reachable")

	case PreferenceGitCredential:
		if helper, ok := gitHelperUsable(); ok {
			return gitSelection(contextName, helper)
		}
		return memorySelection("git is not configured with a credential helper that stores secrets safely")
	}

	if KeyringAvailable() {
		return keyringSelection(contextName)
	}
	if helper, ok := gitHelperUsable(); ok {
		return gitSelection(contextName, helper)
	}
	return memorySelection("no " + KeyringName() + " and no usable git credential helper")
}

func keyringSelection(contextName string) Selection {
	return Selection{
		Storage: NewKeyringStorage(contextName),
		Backend: BackendKeyring,
		Detail:  "Secrets are stored in the " + KeyringName() + ".",
	}
}

func gitSelection(contextName, helper string) Selection {
	return Selection{
		Storage: NewGitCredentialStorageWithContext(contextName),
		Backend: BackendGitCredential,
		Detail:  "Secrets are stored by the git credential helper (" + helper + ").",
	}
}

// SessionOnly returns a Selection that keeps secrets in this process and
// nowhere else. Select falls back to it, and the router starts on it before it
// has resolved a real backend — a Selection is never nil, so nothing has to
// guard against a missing store.
func SessionOnly(why string) Selection {
	return Selection{
		Storage: NewMemoryStorage(),
		Backend: BackendMemory,
		Detail:  "Nothing is saved — " + why + ". You will have to authenticate again next launch.",
	}
}

func memorySelection(why string) Selection {
	return SessionOnly(why)
}

// gitHelperUsable reports whether git has a credential helper configured that
// is worth delegating to, and names it.
//
// `store` is refused by name: it keeps credentials in ~/.git-credentials in
// plaintext, which is the failure this whole change exists to remove — moving
// the token from one plaintext file to another is not a fix. An unset helper is
// refused too, since git would then have nowhere to put the secret and would
// quietly succeed at storing nothing.
//
// Every other helper is accepted. There is no list of the good ones to check
// against: `manager`, `osxkeychain`, `libsecret`, `wincred` and any number of
// third-party helpers all reach a real store, and enumerating them would only
// mean rejecting the next one someone installs.
func gitHelperUsable() (string, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), gitConfigTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "config", "--get-all", "credential.helper")
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	cmd.WaitDelay = credentialWaitDelay
	if err := cmd.Run(); err != nil {
		return "", false
	}

	// git resolves the last helper that answers, so read them in that order and
	// take the first usable one from the end.
	lines := strings.Split(strings.TrimSpace(stdout.String()), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if name, ok := usableHelperName(lines[i]); ok {
			return name, true
		}
	}
	return "", false
}

// usableHelperName extracts the helper name from one credential.helper value
// and reports whether it stores secrets somewhere other than a plaintext file.
func usableHelperName(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", false
	}

	// A value may carry arguments (`store --file=/path`), and a leading `!`
	// marks a shell command. Only the first word names the helper.
	name := strings.TrimPrefix(strings.Fields(value)[0], "!")
	if name == "store" {
		return "", false
	}
	return name, true
}

// Package engine names the container engine DevDesk drives — docker or podman —
// and carries everything about it that is not the same between the two.
//
// It exists as its own package rather than as a field of internal/docker
// because internal/scan needs the same answer and does not import
// internal/docker. That is the internal/forge arrangement read one level down:
// the thing every caller shares does not live inside one of its callers.
//
// What a Shape carries is what measurement, not taste, put there (§3.67):
//
//   - the binary, which is the cheap part — internal/docker already funnels
//     every invocation through one runner;
//   - the credential helper prefix and the auth file, because that file is read
//     *and written* directly rather than through the CLI;
//   - the host socket, which is the one path that breaks rather than moves:
//     rootless podman has no /var/run/docker.sock, and its own socket exists
//     only while `podman system service` runs;
//   - the output templates, which are the silent risk. See Templates.
//
// Nothing here sniffs. A shape is declared, the way a forge's is and the way a
// registry's `provider` is (§3.8): a thing is treated as what it says it is.
package engine

import (
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

// Shape is one container engine: what to run, where it keeps its credentials,
// and how to ask it for machine-readable output.
type Shape struct {
	// Name identifies the engine for a config discriminator, a log line, and
	// the word the views show — "docker", "podman".
	Name string

	// Binary is what gets executed. It is the engine's own name for the two
	// declared shapes, and an explicit path when the configuration names one.
	Binary string

	// HelperPrefix is what a credential helper's name is prefixed with:
	// `docker-credential-osxkeychain`, `podman-credential-…`. The protocol is
	// shared, the naming is not.
	HelperPrefix string

	// Templates are the --format strings for every output this application
	// parses.
	Templates Templates
}

// A Shape carries no resolved filesystem path, and that is deliberate: the
// credential file and the socket are looked up through AuthPaths(), AuthPath()
// and HostSocket() at the moment they are needed.
//
// Storing them on the struct was tried and reverted. The shape is built once,
// at package initialisation, so a $HOME or $XDG_RUNTIME_DIR read there is
// frozen before anything else runs — and the socket is worse, since whether it
// exists is the entire question and it can appear (`podman system service`) or
// vanish while the application is up. A cached answer to "where is the file"
// is a cached answer to "does it exist", which is not a thing a shape can know
// once and for all.

// Templates holds one Go template per parsed output.
//
// They are a field of the shape rather than constants at the call sites for a
// reason that has not been measured away: podman implements --format, but
// equality of the *fields* is guaranteed nowhere, and {{.Ports}} and
// {{.CreatedAt}} are the likeliest to diverge. A divergence raises no error —
// it produces wrong rows, which is the defect class this repository keeps
// cataloguing (D24, D25, D57).
//
// Both shapes therefore declare the same templates today, and that is the
// honest state: no measurement has been taken against a real podman. What this
// indirection buys is that a divergence found later is one line here rather
// than a refactor. Do not collapse it back into constants without that
// measurement (§3.67).
//
// The twelfth parsed output has no template and is not here: `system df -v` is
// a fixed-width table scraped by column offsets (internal/docker/images.go),
// because no --format exposes per-image unique size. See ParsesSystemDFVerbose.
type Templates struct {
	// PS lists containers: id, name, image, state, status, created, ports.
	PS string
	// PSState asks for nothing but the state column, to count containers.
	PSState string
	// Stats is the live resource sample, taken with --no-stream.
	Stats string
	// Info is the host's capacity: CPU count and total memory.
	Info string
	// ImageLS lists images: id, repository, tag, size, created.
	ImageLS string
	// ImageInspect reads the sizes of several images in one call.
	ImageInspect string
	// ImageExposedPorts reads an image's EXPOSE declarations as JSON.
	ImageExposedPorts string
	// NetworkLS lists networks: id, name, driver, scope, created.
	NetworkLS string
	// VolumeLS lists volumes: name, driver, mountpoint.
	VolumeLS string
	// SystemDF is the disk report, one row per resource family.
	SystemDF string
	// Version is the client version, for the dashboard's tools table.
	Version string
}

// ParsesSystemDFVerbose reports whether `<engine> system df -v` prints the
// fixed-width "Images space usage:" table internal/docker scrapes for per-image
// unique size and container count.
//
// Only docker is known to. Under podman the columns are left empty rather than
// filled from offsets taken on a header that may not be the same one: a blank
// column reads as an absence, a value sliced out of the wrong column does not.
func (s Shape) ParsesSystemDFVerbose() bool { return s.Name == Docker }

// Engine names, shared with the configuration. They are duplicated in
// internal/config rather than imported from it so that config does not depend
// on this package; TestEveryConfiguredEngineHasAShape holds the two in step,
// the same arrangement the forge names have (§3.6).
const (
	// Docker is what `auto` resolves to when both engines are installed, and
	// what an unrecognised name falls back to.
	Docker = "docker"
	Podman = "podman"
)

// Auto asks for whichever engine is installed. It is the default, so that
// nobody who installed exactly one of the two is asked which one they meant —
// app.secret_backend's precedent (§3.9).
const Auto = "auto"

// dockerTemplates is the set every call in this application was written
// against. podmanTemplates is a copy, and stays a copy until the measurement
// described on Templates has been made.
var dockerTemplates = Templates{
	PS:                "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.CreatedAt}}\t{{.Ports}}",
	PSState:           "{{.State}}",
	Stats:             "{{.ID}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.MemPerc}}\t{{.NetIO}}\t{{.BlockIO}}",
	Info:              "{{.NCPU}}\t{{.MemTotal}}",
	ImageLS:           "{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}",
	ImageInspect:      "{{.ID}}\t{{.Size}}",
	ImageExposedPorts: "{{json .Config.ExposedPorts}}",
	NetworkLS:         "{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}",
	VolumeLS:          "{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}",
	SystemDF:          "{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}",
	Version:           "{{.Client.Version}}",
}

var podmanTemplates = dockerTemplates

// current is the resolved engine. It starts as docker so that every caller has
// a usable answer before the router has read a configuration — which is what
// the application did before this package existed, and what a test that never
// resolves anything should keep seeing.
var (
	currentMu sync.RWMutex
	current   = shapeFor(Docker, Docker)
)

// Current returns the engine in use.
func Current() Shape {
	currentMu.RLock()
	defer currentMu.RUnlock()
	return current
}

// SetCurrent installs the resolved engine. The router calls it once at startup
// and once per context switch, from Update — never from a Cmd (Rule 110).
func SetCurrent(s Shape) {
	currentMu.Lock()
	defer currentMu.Unlock()
	current = s
}

// Names lists the engines a shape is declared for, in the order the
// configuration view cycles them.
func Names() []string { return []string{Docker, Podman} }

// Resolve turns an app.container_engine value into the engine to drive.
//
// The four cases:
//
//	""/"auto"  docker if it is on PATH, else podman, else an error naming both
//	"docker"   pinned; absent is an error
//	"podman"   pinned; absent is an error
//	anything   taken as a path to a binary
//
// A pinned engine that is not installed is an error rather than a fall back to
// the other one. That is credentials.Select's rule (§3.9), and for the same
// reason: someone who asked for podman should not silently get docker, because
// the two do not hold the same containers.
func Resolve(preference string) (Shape, error) {
	switch preference {
	case "", Auto:
		for _, name := range Names() {
			if _, err := exec.LookPath(name); err == nil {
				return shapeFor(name, name), nil
			}
		}
		return Shape{}, fmt.Errorf("no container engine found: neither %s nor %s is on PATH", Docker, Podman)

	case Docker, Podman:
		if _, err := exec.LookPath(preference); err != nil {
			return Shape{}, fmt.Errorf("%s not found: %w", preference, err)
		}
		return shapeFor(preference, preference), nil
	}

	// Anything else is a path. The engine it belongs to is read from the file
	// name — the one place this package guesses, and it guesses about a value
	// the user typed rather than about the world. Getting it wrong costs the
	// auth file location, not the invocation.
	path := preference
	if _, err := exec.LookPath(path); err != nil {
		return Shape{}, fmt.Errorf("container engine %q not found: %w", path, err)
	}
	return shapeFor(engineOfPath(path), path), nil
}

// engineOfPath reads an engine name out of a configured path. Everything that
// is not recognisably podman is treated as docker, which is what an unknown
// docker-compatible CLI (nerdctl, a wrapper script) behaves like.
func engineOfPath(path string) string {
	base := strings.ToLower(filepath.Base(path))
	base = strings.TrimSuffix(base, ".exe")
	if strings.HasPrefix(base, Podman) {
		return Podman
	}
	return Docker
}

// shapeFor builds the shape for one engine, running the given binary.
func shapeFor(name, binary string) Shape {
	if name == Podman {
		return Shape{
			Name:         Podman,
			Binary:       binary,
			HelperPrefix: "podman-credential-",
			Templates:    podmanTemplates,
		}
	}
	return Shape{
		Name:         Docker,
		Binary:       binary,
		HelperPrefix: "docker-credential-",
		Templates:    dockerTemplates,
	}
}

// ShapeFor returns the declared shape for an engine name, running that name as
// its binary. It answers the configuration view, which needs the shapes before
// anything has been resolved — internal/forge's reason for holding its shapes
// in a table rather than on its backends.
func ShapeFor(name string) Shape { return shapeFor(name, name) }

package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string

	// NetworksCount does **not** come from `docker system df`, which has no row
	// for networks: they hold no bytes, so the disk report ignores them. It is
	// counted by a separate `docker network ls`, and it is the only figure in
	// this struct that costs a second call.
	NetworksCount int

	// BuildCacheSize is the fourth row `docker system df` prints, and the one
	// that answers "where did the disk go" most often — a build cache commonly
	// reaches tens of gigabytes. It was already part of the reclaimable sum;
	// only its own size used to be discarded.
	BuildCacheSize string

	// Reclaimable is what `docker system df` already reports and this package
	// used to drop on the floor: the space a prune would free, summed across
	// the three families. Docker gives it as "12.3GB (45%)" — only the size
	// is kept, the percentage is relative to its own family and would make no
	// sense once added up.
	Reclaimable string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format", templates().SystemDF)
	if err != nil {
		return stats
	}

	stats.Available = true
	var reclaimable int64

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 4)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]
		if len(parts) >= 4 {
			// "12.3GB (45%)" — the percentage is relative to its own family
			// and would not survive an addition.
			reclaimable += parseSize(strings.TrimSpace(strings.Split(parts[3], "(")[0]))
		}

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		case "Build Cache":
			stats.BuildCacheSize = size
		}
	}

	if reclaimable > 0 {
		stats.Reclaimable = formatSize(reclaimable)
	}

	// A list that fails leaves the count at zero rather than failing the
	// whole call: the sizes were just read and are worth returning.
	if networks, err := ListNetworks(); err == nil {
		stats.NetworksCount = len(networks)
	}

	return stats
}

