{"query":"wizard validates GitLab token save credential during setup","repo_root":"/c/Users/anthoni/projects/entire/anthnel/devdesk/.worktrees/feat/setup-wizard","commit":"3a7c02f62157849ce7ac91332ec075de7bbec094","tree":"57505ad5fbdcbfd75960c3282661baec21699d8b","profile":"full","results":[{"rank":1,"score":55.4552,"file_path":"internal/config/forge.go","start_line":24,"end_line":81,"focus_line":40,"snippet_start_line":32,"snippet_end_line":81,"symbol_start_line":32,"symbol_end_line":81,"language":"Go","kind":"function","symbol_id":"local/setup-wizard:Go:internal/config/forge.go:function:migrateGitLabSection","symbol_name":"migrateGitLabSection","qualified_name":"migrateGitLabSection","signature":"func migrateGitLabSection(cfg *Config)","signals":["body","symbol-name","constraint:entity","exact-code-token","graph:callers","complete-symbol"],"snippet":"func migrateGitLabSection(cfg *Config) {
	legacy := cfg.GitLab
	if legacy == (GitLabConfig{}) {
		return
	}
	defer func() {
		// A legacy file predates `type:` by definition, so it can only mean
		// GitLab. Cleared last, so the key leaves the file on the next save.
		if cfg.Forge.Type == "" {
			cfg.Forge.Type = ForgeGitLab
		}
		cfg.GitLab = GitLabConfig{}
	}()

	// Nothing under `forge:` at all — the ordinary case, and the only one where
	// a bool can be carried over safely: IncludeArchived's zero value *is*
	// false, so no per-field guard could tell "unset" from "deliberately off".
	if cfg.Forge == (ForgeConfig{}) {
		cfg.Forge = ForgeConfig{
			URL:                legacy.URL,
			DefaultParentGroup: legacy.DefaultParentGroup,
			DefaultVisibility:  legacy.DefaultVisibility,
			CloneMethod:        legacy.CloneMethod,
			Pull: ForgePullConfig{
				ParallelJobs:    legacy.Pull.ParallelJobs,
				IncludeArchived: legacy.Pull.IncludeArchived,
			},
		}
		return
	}

	// Both blocks are present, which a hand-edited file can be. The new one
	// wins field by field: its values were written later, and overwriting them
	// with the old ones would undo the edit that created the situation.
	if cfg.Forge.URL == "" {
		cfg.Forge.URL = legacy.URL
	}
	if cfg.Forge.DefaultParentGroup == "" {
		cfg.Forge.DefaultParentGroup = legacy.DefaultParentGroup
	}
	if cfg.Forge.DefaultVisibility == "" {
		cfg.Forge.DefaultVisibility = legacy.DefaultVisibility
	}
	if cfg.Forge.CloneMethod == "" {
		cfg.Forge.CloneMethod = legacy.CloneMethod
	}
	if cfg.Forge.Pull.ParallelJobs == 0 {
		cfg.Forge.Pull.ParallelJobs = legacy.Pull.ParallelJobs
	}
}","comment_focus_line":39},{"rank":2,"score":55.4535,"file_path":"internal/app/app.go","start_line":384,"end_line":388,"focus_line":387,"snippet_start_line":384,"snippet_end_line":388,"symbol_start_line":348,"symbol_end_line":530,"language":"Go","kind":"method","symbol_id":"local/setup-wizard:Go:internal/app/app.go:method:App.Update","symbol_name":"Update","qualified_name":"App.Update","signature":"func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd)","signals":["body","symbol-usage"],"snippet":"		return a.handleContextList(msg)

