}

// resolveContainerEngine picks up the new app.container_engine for this
// context.
//
// Every view that lists containers, images, networks or volumes is rebuilt by
// the caller right after this, so nothing carries the previous engine's
// listings forward — which matters here more than it does for a theme: two
// engines do not hold the same containers, and a stale row would name something
// that does not exist.
//
// A preference that does not resolve is **not** fatal and does not fall back to
// the other engine. The previous shape is kept and the views report the absence
// the way they always have when the binary is missing (requireEngine) — an
// error at the moment of use, naming the engine that was asked for, rather than
// a silent substitution that answers about the wrong machine (§3.67).
func (a *App) resolveContainerEngine() {
	preference := a.config.App.ContainerEngine
	shape, err := engine.Resolve(preference)
	if err != nil {
		log.Printf("ERROR [app] resolve container engine %q: %v", preference, err)
		return
	}
	engine.SetCurrent(shape)
	log.Printf("Container engine for context %s resolved to %s (%s)",
		a.currentContext, shape.Name, shape.Binary)
}

// closeForgeSession drops the client-side session after the forge's URL or its
// platform changed. The session was established against the previous one, so
// keeping it would mean the next call fails somewhere far from the cause.
//
// Nothing is revoked and no token is deleted: the user changed an address or a
// platform, not their credentials, and a token for the old host is still
// theirs — and it is still what the store holds for that URL.
func (a *App) closeForgeSession() {
	if !a.sharedState.IsAuthenticated {
		return
	}
	log.Printf("Forge changed; closing the session for context %s", a.currentContext)
	a.clearAuthenticated()
}

}

// Status is what a view derives on every frame: a progress line, a hint, or a
// table loading its rows. It carries no timer — a batch outlives the three
// seconds a message gets, which is why the sync and prune lines were rendered
// from state rather than assigned to footerInfo in the first place.
//
// It is a parameter of View rather than a field of FooterMessage because it is
// derived, not stored: containers' action line comes from BusyLabels(), which
// changes with no event to push it on.
type Status struct {
	Text string
	// Spinner prepends the current spinner frame — a table loading its rows.
	Spinner bool
	// Level colours the line, and the zero value is LevelInfo, so a status that
	// says nothing about it renders exactly as it always did.
	//
	// A derived state can be a failure as legitimately as it can be progress:
	// "Docker unreachable" is not an event that happened once, it is what is
	// true right now, and a message would expire after three seconds — which is
	// D47 in one field. It needs the colour of an error and the lifetime of a
	// state, and only Status can give it both.
	Level Level
}

// footerMsgSeq numbers messages so a timer can name the one it was started for.
var footerMsgSeq atomic.Uint64

// ClearFooterMsg expires the message identified by ID.
//
// The ID is what makes the type safe to share across packages. Two things would
// otherwise go wrong: a timer started by one view could clear the message of
// whichever view is active when it lands, and — the bug that was already
// present in all eight local implementations — a message set at t+2.9s was
// wiped at t+3s by its predecessor's timer.
type ClearFooterMsg struct{ ID uint64 }

// PostFooterMsg puts a message in whichever footer is on screen.
//
// It exists for the router, which has none of its own: RenderFooter is the

